const tg=window.Telegram?.WebApp;
tg?.ready();tg?.expand();
const app=document.querySelector('#app');
const state={tab:'home',filter:'all',when:'all',court:'all',genderFilter:'all',myLevelOnly:false,availableOnly:false,trainingSport:'all',trainingGender:'all',trainingCourts:[],trainingFormat:'all',games:[],catalog:{coaches:[],courts:[]},trainings:[],weather:[],weatherStatus:'loading',weatherFetched:false,people:[],peopleQuery:'',peopleOffset:0,peopleMore:false,inbox:[],unread:0,chat:null,chatThreads:null,history:[],me:null,config:{},detail:null,trainingDetail:null,userProfile:null,form:'',profilePhotoData:null,avatarId:null,registrationStep:1,registrationRole:null,registrationDraft:null,pendingGame:null,loading:true};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(iso,opts)=>new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',...opts}).format(new Date(iso));
const day=iso=>fmt(iso,{day:'numeric',month:'short'});
const hour=iso=>fmt(iso,{hour:'2-digit',minute:'2-digit'});
const dayKey=iso=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(iso));
const tomorrow=()=>{const d=new Date(Date.now()+86400000);return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)};
let demoId=localStorage.getItem('tennis-go-demo-id');if(!demoId){demoId='demo-'+crypto.randomUUID();localStorage.setItem('tennis-go-demo-id',demoId);}
function headers(){return tg?.initData?{'Authorization':'tma '+tg.initData}:{'X-Demo-User':demoId,'X-Demo-Name':encodeURIComponent('Роман')};}
async function api(route,method='GET',payload){const res=await fetch('/api'+route,{method,headers:{...headers(),...(payload?{'Content-Type':'application/json'}:{})},body:payload?JSON.stringify(payload):undefined});const data=await res.json();if(!res.ok)throw new Error(data.error||'Ошибка сети');return data;}
function toast(message){document.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.textContent=message;document.body.append(n);setTimeout(()=>n.remove(),3300);tg?.HapticFeedback?.notificationOccurred?.('success');}
async function refresh(){const [g,m,c,t,i]=await Promise.all([api('/games'),api('/me'),api('/catalog'),api('/trainings'),api('/inbox')]);state.games=g.games;state.me=m.user;state.catalog=c;state.trainings=t.trainings;state.inbox=i.threads||[];state.unread=i.unread||0;if(!state.weatherFetched){state.weatherFetched=true;loadWeather();}}
async function loadWeather(){try{const w=await api('/weather');state.weather=w.hours||[];state.weatherStatus=w.status||'unavailable';}catch{state.weather=[];state.weatherStatus='unavailable';}if(!state.loading&&state.me?.registered&&!state.form&&!state.chat)render();}
async function loadInbox(updatePage=true){const data=await api('/inbox');state.inbox=data.threads||[];state.unread=data.unread||0;const badge=document.querySelector('#chat-badge');if(badge){badge.textContent=state.unread||'';badge.hidden=!state.unread;}if(updatePage&&state.tab==='chats'&&!state.chat)render();}
async function loadPeople(reset=false){const offset=reset?0:state.peopleOffset,search=state.peopleQuery;const data=await api('/users?q='+encodeURIComponent(search)+'&offset='+offset);if(search!==state.peopleQuery)return;state.people=reset?data.users:[...state.people,...data.users];state.peopleOffset=offset+data.users.length;state.peopleMore=!!data.hasMore;render();}
const avatarChoices=[['male-serve','Подача','Мужские'],['male-cap','Кепка','Мужские'],['male-court','У сетки','Мужские'],['female-serve','Подача','Женские'],['female-cap','Козырёк','Женские'],['female-court','У сетки','Женские']];
function tennisAvatar(id){return `<span class="tennis-avatar avatar-sprite avatar-${id}" role="img" aria-label="Мультяшная теннисная аватарка"></span>`;}
function avatar(u){return u?.photoData?`<img src="${esc(u.photoData)}" alt="Фото профиля">`:u?.avatarId&&avatarChoices.some(([id])=>id===u.avatarId)?tennisAvatar(u.avatarId):esc((u?.name||'Р').slice(0,1).toUpperCase());}
function participantStrip(members){return members.length?`<span class="participant-strip" aria-label="Записались: ${esc(members.map(m=>m.name).join(', '))}">${members.slice(0,4).map(m=>`<span class="participant-mini">${avatar(m)}</span>`).join('')}${members.length>4?`<span class="participant-more">+${members.length-4}</span>`:''}</span>`:'<span class="participant-none">Пока нет записавшихся</span>';}
function participantRows(members){return members.length?members.map(m=>`<button class="participant-row" data-user="${esc(m.id)}"><span class="avatar">${avatar(m)}</span><strong>${esc(m.name)}</strong><span class="participant-next">Профиль →</span></button>`).join(''):'<p class="muted">Пока никто не записался.</p>';}
function genderName(value){return value==='female'?'женщины':value==='male'?'мужчины':'любой пол';}
function padelIcon(){return `<svg class="sport-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-label="Ракетка для падела" role="img"><path d="M12 2.2C6.9 2.2 4 5.7 4 10c0 3.7 2.3 6.4 5.7 7.2l.9.2 1.4 1.6 1.8-1.7-.9-1.2c4-1.3 6.1-4.2 6.1-8.1 0-4.3-2.7-7.8-7-7.8Z"/><path d="m12 19 3.8 3 1.5-1.6-3.5-3.1"/><circle cx="9" cy="7" r=".8"/><circle cx="13" cy="7" r=".8"/><circle cx="7.5" cy="11" r=".8"/><circle cx="11.5" cy="11" r=".8"/><circle cx="15.5" cy="11" r=".8"/><circle cx="10" cy="14.5" r=".8"/><circle cx="14" cy="14.5" r=".8"/></svg>`;}
function logo(){return `<header class="top"><span class="brand-logo"><img src="/assets/tennis-go-approved-logo.png" alt="Tennis GO"></span><span class="top-spacer"></span><span class="city-pill">⌖ ${esc(state.me?.city||'Краснодар')}</span><span class="avatar">${avatar(state.me)}</span></header>`;}
function nav(){return `<nav class="nav">${[['home','⌂','Главная'],['games','⚑','Игры'],['training','◷','Тренировки'],['people','♙','Люди'],['chats','✉','Чаты'],['profile','○','Профиль']].map(([id,icon,label])=>`<button data-tab="${id}" class="${state.tab===id?'active':''}"><i>${icon}</i>${label}${id==='chats'?`<span id="chat-badge" class="nav-unread" ${state.unread?'':'hidden'}>${state.unread||''}</span>`:''}</button>`).join('')}</nav>`;}
function weatherCredit(){return `<p class="footer-note">${state.weatherStatus==='unavailable'?'Прогноз временно недоступен · ':''}Прогноз: <a href="https://open-meteo.com" target="_blank" rel="noopener noreferrer">Open-Meteo</a> · Tennis GO ${esc(state.config.version||'0.14.0')}</p>`;}
function weatherBadge(startsAt){const target=Date.parse(startsAt);if(!Number.isFinite(target)||target<Date.now()-3600000)return '';const hour=state.weather.find(x=>Math.abs(Date.parse(x.time)-target)<=30*60000);if(!hour||!Number.isFinite(hour.temperature))return `<span class="weather-missing" title="${state.weatherStatus==='unavailable'?'Погодный сервис недоступен':'Прогноз для этой даты ещё не опубликован'}">${state.weatherStatus==='unavailable'?'Погода недоступна':'Прогноз позже'}</span>`;const code=Number(hour.code),icon=code<=1?'☀️':code<=3||code===45||code===48?'☁️':'🌧️',label=code<=1?'Ясно':code<=3||code===45||code===48?'Пасмурно':'Осадки';return `<span class="weather-badge" title="Прогноз: ${label} · Open-Meteo" aria-label="${label}, ${Math.round(hour.temperature)} °C">${icon} ${Math.round(hour.temperature)}°</span>`;}
function gameCard(g){const places=g.seats-g.members.length;return `<article class="card listing-card game-list-card"><div class="listing-head"><span class="listing-kicker">СПАРРИНГ${g.seats>2?' / ПАРНАЯ':''} · ${g.sport==='tennis'?'ТЕННИС':'ПАДЕЛ'}</span><span class="listing-date">${g.cancelled?'ОТМЕНЕНА · ':''}${day(g.startsAt)} · ${hour(g.startsAt)} ${weatherBadge(g.startsAt)}</span></div><h3 class="game-title">${esc(g.venue)}</h3><p class="listing-address">${esc(g.courtAddress||g.city)} · ${g.duration} мин</p><div class="listing-meta"><span>NTRP ${g.levelMin}–${g.levelMax}</span><span class="listing-places">${places?`Свободно мест: ${places}`:'Мест нет'}</span><strong>${g.price} ₽/чел.</strong></div><div class="listing-bottom">${participantStrip(g.members)}<span class="listing-actions"><button class="small-btn outline" data-chat="game:${g.id}">Написать</button><button class="small-btn outline" data-game="${g.id}">${g.joined?'Моя игра →':'Подробнее →'}</button></span></div></article>`;}
function filters(){return `<div class="filters" aria-label="Вид спорта">${[['all','Все игры'],['tennis','🎾 Теннис'],['padel',`${padelIcon()} Падел`]].map(([v,l])=>`<button class="chip ${state.filter===v?'active':''}" data-filter="${v}" aria-pressed="${state.filter===v}">${l}</button>`).join('')}</div>`;}
function visibleGames({mine=false,advanced=false,ignoreSport=false}={}){const today=dayKey(Date.now()),next=dayKey(Date.now()+86400000),weekEnd=Date.now()+7*86400000;return state.games.filter(g=>{const time=Date.parse(g.startsAt),places=g.seats-g.members.length;if(g.cancelled||time<Date.now()-3600000||mine&&!g.joined||!ignoreSport&&state.filter!=='all'&&g.sport!==state.filter)return false;if(!advanced)return true;if(state.availableOnly&&places<=0||state.court!=='all'&&g.courtId!==state.court||state.genderFilter!=='all'&&g.creatorGender!==state.genderFilter||state.myLevelOnly&&(g.creatorRole!=='player'||g.creatorNtrp==null||state.me?.ntrpLevel==null||Math.abs(Number(g.creatorNtrp)-Number(state.me.ntrpLevel))>1)||!g.joined&&g.opponentGender!=='any'&&g.opponentGender!==state.me?.gender)return false;return state.when==='all'||state.when==='today'&&dayKey(time)===today||state.when==='tomorrow'&&dayKey(time)===next||state.when==='week'&&time<=weekEnd;}).sort((a,b)=>Date.parse(a.startsAt)-Date.parse(b.startsAt));}
function gamesList(mine=false,limit=0,advanced=false){const games=visibleGames({mine,advanced});return games.length?games.slice(0,limit||games.length).map(gameCard).join(''):`<div class="card empty"><div class="icon">🎾</div><strong>${mine?'Пока нет ваших игр':'Пока нет подходящих игр'}</strong><div class="muted">${advanced?'Попробуйте изменить фильтры или создайте свою игру':'Создайте игру и пригласите первого партнёра'}</div>${advanced?'<button class="small-btn outline" data-reset-filters style="margin-top:12px">Сбросить фильтры</button>':'<button class="small-btn" data-page="create" style="margin-top:12px">Создать игру</button>'}</div>`;}
function compactGameCard(g){const places=g.seats-g.members.length;return `<button class="card compact-card compact-game" data-game="${g.id}"><span class="compact-line"><span class="compact-kicker">СПАРРИНГ${g.seats>2?' / ПАРНАЯ':''}</span><span class="compact-date">${day(g.startsAt)} · ${hour(g.startsAt)} ${weatherBadge(g.startsAt)}</span></span><strong class="compact-title">${g.sport==='tennis'?'Теннис':`${padelIcon()} Падел`} · ${esc(g.venue)}</strong><span class="compact-footer"><span>NTRP ${g.levelMin}–${g.levelMax}</span><span class="compact-places">${participantStrip(g.members)}${places} ${places===1?'место':places<5?'места':'мест'}</span><span class="compact-price">${g.price} ₽/чел.</span></span></button>`;}
function compactTrainingCard(t){const places=t.seats-t.members.length;return `<button class="card compact-card compact-training" data-training="${t.id}"><span class="avatar">${avatar({name:t.coachName,photoData:t.coachPhotoData,avatarId:t.coachAvatarId})}</span><span class="compact-main"><span class="compact-line"><span class="compact-kicker">ТРЕНИРОВКА / ${t.sport==='padel'?'ПАДЕЛ':'ТЕННИС'}</span><span class="compact-date">${day(t.startsAt)} · ${hour(t.startsAt)} ${weatherBadge(t.startsAt)}</span></span><strong class="compact-trainer">Тренер - ${esc(t.coachName)}</strong><span class="compact-format">${trainingFormat[t.format]||'Тренировка'} · стаж ${t.coachYears==null?'не указан':`${t.coachYears} лет`}</span><span class="compact-footer"><span class="compact-places">${participantStrip(t.members)}${places} ${places===1?'место':places<5?'места':'мест'} свободно</span><span class="compact-price">${t.price} ₽/чел.</span></span></span></button>`;}
function home(){const games=visibleGames({ignoreSport:true}).filter(g=>g.seats>g.members.length).slice(0,2),trainings=state.trainings.filter(t=>Date.parse(t.startsAt)>=Date.now()-3600000&&!t.cancelled&&t.seats>t.members.length).sort((a,b)=>Date.parse(a.startsAt)-Date.parse(b.startsAt)).slice(0,2);return `<div class="content"><div class="hero"><img src="/assets/hero_court.png" alt="Теннис делает жизнь ярче"></div><div class="quick"><button class="primary" data-tab="games"><span>↗</span>Найти игру →</button><button class="secondary" data-page="create"><span>＋</span>Создать игру →</button>${state.me?.role==='coach'?'<button class="primary training-action" data-page="create-training"><span>＋</span>Создать тренировку →</button>':''}</div><section class="home-section games-section"><div class="section-head"><h2>Ближайшие игры</h2><button class="text-btn" data-tab="games">Все →</button></div>${games.length?games.map(compactGameCard).join(''):'<div class="card compact-empty">Пока нет игр со свободными местами</div>'}</section><section class="home-section trainings-section"><div class="section-head"><h2>Тренировки</h2><button class="text-btn" data-tab="training">Все →</button></div>${trainings.length?trainings.map(compactTrainingCard).join(''):'<div class="card compact-empty">Пока нет тренировок со свободными местами</div>'}</section>${weatherCredit()}${state.config.demo?'<p class="footer-note">Демо режим · карточки и расписание для примера</p>':''}</div>`;}

function gamesPage(){const courts=state.catalog.courts.filter(c=>state.filter==='all'||c.sport===state.filter);return `<div class="content subpage"><div class="page-heading"><div><h1 class="page-title">Найти игру</h1><p class="lead">Игроки и корты Краснодара рядом с вами.</p></div><button class="add-game" data-page="create" aria-label="Создать игру">＋</button></div>${filters()}<div class="search-panel"><div class="date-filters" aria-label="Дата игры">${[['all','Любая дата'],['today','Сегодня'],['tomorrow','Завтра'],['week','7 дней']].map(([v,l])=>`<button class="date-chip ${state.when===v?'active':''}" data-when="${v}" aria-pressed="${state.when===v}">${l}</button>`).join('')}</div><label class="field">Корт<select id="court-filter" aria-label="Корт"><option value="all">Все корты</option>${courts.map(c=>`<option value="${esc(c.id)}" ${state.court===c.id?'selected':''}>${esc(c.name)} · ${esc(c.address)}</option>`).join('')}</select></label><label class="field">Пол создателя игры<select id="gender-filter" aria-label="Пол создателя игры"><option value="all">Любой пол</option><option value="female" ${state.genderFilter==='female'?'selected':''}>Женщина</option><option value="male" ${state.genderFilter==='male'?'selected':''}>Мужчина</option></select></label><p class="hint" style="margin:-5px 0 9px">Показываем игры, доступные вам для участия.</p><button class="availability ${state.myLevelOnly?'active':''}" data-my-level aria-pressed="${state.myLevelOnly}" ${state.me?.ntrpLevel==null?'disabled':''}><span class="availability-dot"></span> Игроки моего уровня · ±1 NTRP</button><p class="hint" style="margin:0 0 9px">${state.me?.ntrpLevel==null?'Для фильтра укажите свой NTRP в профиле.':'Игры игроков с NTRP от '+Math.max(1,state.me.ntrpLevel-1).toFixed(1)+' до '+Math.min(7,state.me.ntrpLevel+1).toFixed(1)+'.'}</p><button class="availability ${state.availableOnly?'active':''}" data-available aria-pressed="${state.availableOnly}"><span class="availability-dot"></span> Только со свободными местами</button></div><div class="results-head"><strong>Игры</strong><span>${visibleGames({advanced:true}).length} найдено</span></div>${gamesList(false,0,true)}<button class="button" data-page="create">＋ Создать игру</button>${weatherCredit()}</div>`;}
const levelDescriptions={
 tennis:{'1.0':"Игрок только начинает играть в теннис.",'1.5':"Игрок имеет ограниченные навыки игры и еще работает над тем, чтобы держать мяч в игре.",'2.0':"Игрок нуждается в игровом опыте, имеет заметные недостатки при выполнении ударов, но уже знаком с основными положениями одиночных и парных игр.",'2.5':"Игрок учится предугадывать направление мяча, хотя чувство корта развито еще слабо. Может поддерживать игру в невысоком темпе с игроками подобного уровня.",'3.0':"Игрок стабильно отбивает мячи в среднем темпе, но чувствует неуверенность, когда пытается контролировать направление, глубину и силу при выполнении ударов.",'3.5':"Игрок достиг хорошего контроля направления при ударах средней сложности, но еще недостаточно контроля глубины и разнообразия. Решительно играет у сетки и работает над усовершенствованием парной игры.",'4.0':"Игрок выполняет надежные удары, контролирует направление и глубину с форхенда и бекхэнда плюс способен с успехом использовать свечи, смэши, выбивающие удары и удары с лета. Может допускать ошибки при подаче, использует командную тактику в парной игре.",'4.5':"Игрок приобрел навыки использования силы и подкрутки при ударах, начал управлять темпом игры, имеет хорошую работу ног, может контролировать глубину ударов и менять тактику игры в зависимости от противника. Игрок владеет сильной и точной первой, стабильной второй подачей, может атаковать у сетки.",'5.0':"Игрок хорошо чувствует мяч и часто выполняет особенные удары, вокруг которых строится игра. Может выигрывать очки или вынуждать соперника совершать ошибки с помощью укороченных мячей, \"убивать\" мячи с лета, успешно использовать свечи, укороченные удары, удары с полулета или смэши и использовать хорошую глубину и подкрутку на второй подаче.",'5.5':"Игрок в качестве главного оружия использует мощные удары и стабильность. Может менять стратегию и стиль игры в зависимости от ситуации и выполнять надежные удары в стрессовой ситуации.",'6.0':"Игрок не нуждается в рейтинге NTRP. Текущая или прошлая классификация говорит сама за себя. Игрок рейтинга 6.0 обычно соответствует уровню национальных соревнований среди юниоров и имеет национальный рейтинг. Игрок уровня 6.5 приближается к уровню 7.0 и имеет опыт участия в турнирах-сателлитах. Уровень 7.0 - игрок мирового класса, участвующий в турнирах международного уровня и для которого главным источником доходов являются призовые деньги.",'6.5':"Игрок не нуждается в рейтинге NTRP. Текущая или прошлая классификация говорит сама за себя. Игрок рейтинга 6.0 обычно соответствует уровню национальных соревнований среди юниоров и имеет национальный рейтинг. Игрок уровня 6.5 приближается к уровню 7.0 и имеет опыт участия в турнирах-сателлитах. Уровень 7.0 - игрок мирового класса, участвующий в турнирах международного уровня и для которого главным источником доходов являются призовые деньги.",'7.0':"Игрок не нуждается в рейтинге NTRP. Текущая или прошлая классификация говорит сама за себя. Игрок рейтинга 6.0 обычно соответствует уровню национальных соревнований среди юниоров и имеет национальный рейтинг. Игрок уровня 6.5 приближается к уровню 7.0 и имеет опыт участия в турнирах-сателлитах. Уровень 7.0 - игрок мирового класса, участвующий в турнирах международного уровня и для которого главным источником доходов являются призовые деньги."},
 padel:{'1.0':'Первый раз на корте','1.5':'Знакомлюсь с правилами и подачей','2.0':'Возвращаю простые мячи','2.5':'Держу короткий розыгрыш','3.0':'Уверенно играю с партнёром','3.5':'Использую стены и выходы к сетке','4.0':'Контролирую темп и положение команды','4.5':'Меняю тактику и умею защищаться','5.0':'Сильный турнирный любитель','5.5':'Регулярно играю турниры высокого уровня','6.0':'Профессиональный уровень','6.5':'Высокий профессиональный уровень','7.0':'Элита профессионального падела'}
};
function levelOptions(selected,sport='tennis'){return Object.keys(levelDescriptions[sport]).map(v=>`<option value="${v}" ${Number(v)===selected?'selected':''}>${v}</option>`).join('');}
function courtOptions(sport,selected){return state.catalog.courts.filter(c=>c.sport===sport).map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)} — ${esc(c.address)}</option>`).join('');}
function createPage(){return `<div class="content"><h1 class="page-title">Создать игру</h1><p class="lead">Выберите площадку и время, затем пригласите игроков.</p><form id="create-form"><div class="form-card"><h3>01 · Формат игры</h3><div class="seg"><label><input type="radio" name="sport" value="tennis" checked>🎾 Теннис</label><label><input type="radio" name="sport" value="padel">${padelIcon()} Падел</label></div><div class="row" style="margin-top:13px"><label class="field">Игроков<select name="seats"><option value="2">2 игрока</option><option value="4">4 игрока · парная</option></select></label><label class="field">Тип<select name="kind"><option value="friendly">Обычная</option><option value="rating">С результатом</option></select></label></div><label class="field" style="margin-top:12px">Кто может присоединиться<select name="opponentGender"><option value="any">Любой пол</option><option value="female">Только женщины</option><option value="male">Только мужчины</option></select></label><p class="hint">Выбранный пол проверяется при присоединении игроков. Игра со счётом доступна один на один. NTRP в профиле остаётся вашей оценкой навыков.</p></div><div class="form-card"><h3>02 · Где и когда</h3><label class="field">Корт в Краснодаре<select name="courtId" required>${courtOptions('tennis')}</select></label><div class="court-address" id="court-address">${esc(state.catalog.courts.find(c=>c.sport==='tennis')?.address||'')}</div><div class="row"><label class="field">Дата<input type="date" name="date" min="${tomorrow()}" value="${tomorrow()}" required></label><label class="field">Время<input type="time" name="time" value="19:00" required></label></div><div class="row"><label class="field">Продолжительность<select name="duration"><option>60</option><option selected>90</option><option>120</option></select></label><label class="field">₽ / человек<input type="number" name="price" value="1000" min="0" max="100000" required></label></div><p class="hint">Название и адрес подтверждены по данным клубов. Свободные слоты уточняются отдельно.</p></div><div class="form-card"><h3>03 · Подходящий уровень</h3><div class="row"><label class="field">От<select name="levelMin">${levelOptions(2.5)}</select></label><label class="field">До<select name="levelMax">${levelOptions(3.5)}</select></label></div><div class="level-explainer" id="level-summary">2.5 — ${esc(levelDescriptions.tennis['2.5'])}<br>3.5 — ${esc(levelDescriptions.tennis['3.5'])}</div><p class="hint" style="margin:0 0 9px">Ориентир для подбора игроков: теннис — по описаниям NTRP, падел — отдельная условная шкала.</p><details class="level-guide"><summary>Что означают уровни NTRP 1.0–7.0?</summary><div id="level-guide-items">${levelGuide('tennis')}</div></details><label class="field">Комментарий<textarea name="note" maxlength="240" placeholder="Темп игры или важные детали"></textarea></label></div><button class="button" type="submit">Создать игру →</button></form></div>`;}
function levelGuide(sport){return Object.entries(levelDescriptions[sport]).filter(([v])=>sport!=='tennis'||!['6.5','7.0'].includes(v)).map(([v,label])=>`<div><strong>${sport==='tennis'&&v==='6.0'?'6.0–7.0':v}</strong><span>${esc(label)}</span></div>`).join('');}
function updateCreateChoices(form){const sport=form.elements.sport.value,courts=state.catalog.courts.filter(c=>c.sport===sport),courtSelect=form.elements.courtId;
 courtSelect.innerHTML=courtOptions(sport);if(sport==='padel'&&form.elements.kind?.value!=='rating'&&form.elements.seats.value==='2')form.elements.seats.value='4';
 for(const name of ['levelMin','levelMax']){const select=form.elements[name],value=Number(select.value);select.innerHTML=levelOptions(value,sport);}
 form.querySelector('#level-guide-items').innerHTML=levelGuide(sport);syncGameFormat(form);updateCreateHints(form);
}
function syncGameFormat(form){const rating=form.elements.kind?.value==='rating';if(rating)form.elements.seats.value='2';const four=form.elements.seats.querySelector?.('option[value="4"]');if(four)four.disabled=rating;const hint=form.querySelector('.form-card .hint');if(hint)hint.textContent=rating?'Игра со счётом доступна один на один: результат подтвердят оба игрока.':'Обычная игра возможна для двух или четырёх игроков.';}
function updateCreateHints(form){const sport=form.elements.sport.value,court=state.catalog.courts.find(c=>c.id===form.elements.courtId.value),min=form.elements.levelMin.value,max=form.elements.levelMax.value;
 form.querySelector('#court-address').textContent=court?`📍 Краснодар, ${court.address}`:'';
 form.querySelector('#level-summary').innerHTML=`${esc(min)} — ${esc(levelDescriptions[sport]?.[min]||'')}<br>${esc(max)} — ${esc(levelDescriptions[sport]?.[max]||'')}`;
}
function gameDetail(g){const places=g.seats-g.members.length;const canReport=!g.cancelled&&g.joined&&g.kind==='rating'&&g.members.length===2&&Date.parse(g.startsAt)+g.duration*60000<Date.now();return `<div class="content subpage"><div class="detail-cover"><div><span class="eyebrow">СПАРРИНГ · ${g.seats>2?'ПАРНАЯ · ':''}${g.sport==='tennis'?'ТЕННИС':'ПАДЕЛ'} · ${g.kind==='rating'?'С РЕЗУЛЬТАТОМ':'ОБЫЧНАЯ ИГРА'}</span><h1>${esc(g.venue)}</h1></div></div>${g.courtAddress?`<div class="notice">📍 Краснодар, ${esc(g.courtAddress)}</div>`:''}<div class="detail-grid"><div class="stat"><small>Дата и время · МСК</small><strong>${day(g.startsAt)} · ${hour(g.startsAt)}</strong></div><div class="stat"><small>Стоимость</small><strong>${g.price} ₽ / чел.</strong></div><div class="stat"><small>Уровень</small><strong>${g.levelMin}–${g.levelMax}</strong></div><div class="stat"><small>Длительность</small><strong>${g.duration} минут</strong></div><div class="stat"><small>Кого ищут</small><strong>${genderName(g.opponentGender)}</strong></div></div><div class="form-card"><h3>Участники · ${g.members.length}/${g.seats}</h3>${participantRows(g.members)}${places?`<div class="muted" style="padding-top:8px">＋ Свободно мест: ${places}</div>`:''}</div>${g.note?`<div class="notice">${esc(g.note)}</div>`:''}<div class="detail-actions">${!g.cancelled&&!g.joined&&places?'<button class="button" data-action="join">Присоединиться к игре</button>':''}${!g.cancelled&&g.joined?'<button class="button light" data-action="share">↗ Пригласить игрока</button>':''}${!g.cancelled&&g.joined&&g.creatorId!==state.me?.id&&!g.result?'<button class="text-btn" data-action="leave">Покинуть игру</button>':''}</div>${listingControls('game',g)}${g.result?`<div class="form-card" style="margin-top:15px"><h3>Результат · ${esc(g.result)}</h3><div class="muted">Счёт указан от лица создателя · ${g.resultConfirmed?'✅ Подтверждён':'Ожидает подтверждения'}</div>${!g.resultConfirmed&&g.joined&&g.resultBy!==state.me?.id?'<button class="button" data-action="confirm" style="margin-top:12px">Подтвердить счёт</button>':''}</div>`:''}${canReport&&!g.resultConfirmed?`<form id="result-form" class="form-card" style="margin-top:14px"><h3>${g.result?'Исправить':'Записать'} результат</h3><label class="field">Счёт от лица создателя<input name="score" value="${esc(g.result||'')}" placeholder="6:4, 6:3" required></label><button class="button light" type="submit">Отправить на подтверждение</button></form>`:''}${g.kind==='rating'?'<p class="notice">После подтверждения счёт сохраняется в игре. Уровень NTRP в профиле можно менять вручную.</p>':''}</div>`;}
const trainingFormat={individual:'Индивидуальная',split:'Сплит · 2 человека',group:'Группа'};
function trainingCard(t){const available=t.seats-t.members.length;return `<article class="card listing-card training-card"><div class="listing-head"><span class="listing-kicker">ТРЕНИРОВКА / ${t.sport==='padel'?'ПАДЕЛ':'ТЕННИС'}</span><span class="listing-date">${t.cancelled?'ОТМЕНЕНА · ':''}${day(t.startsAt)} · ${hour(t.startsAt)} ${weatherBadge(t.startsAt)}</span></div><div class="listing-trainer"><span class="avatar">${avatar({name:t.coachName,photoData:t.coachPhotoData,avatarId:t.coachAvatarId})}</span><div><strong>Тренер - ${esc(t.coachName)}</strong><small>${trainingFormat[t.format]||'Тренировка'} · стаж ${t.coachYears==null?'не указан':`${t.coachYears} лет`}</small></div></div><p class="listing-address">${esc(t.courtName)} · ${esc(t.courtAddress)}</p><div class="listing-meta"><span>${t.ntrpMin==null?'Без NTRP':`NTRP ${Number(t.ntrpMin).toFixed(1)}–${Number(t.ntrpMax).toFixed(1)}`}</span><span class="listing-places">${available?`Свободно мест: ${available}`:'Мест нет'}</span><strong>${t.price} ₽/чел.</strong></div><div class="listing-bottom">${participantStrip(t.members)}<span class="listing-actions"><button class="small-btn outline" data-chat="training:${t.id}">Написать</button><button class="small-btn outline" data-training="${t.id}">Подробнее →</button></span></div></article>`;}

function filteredTrainings(){return state.trainings.filter(t=>!t.cancelled&&(state.trainingSport==='all'||t.sport===state.trainingSport)&&(state.trainingGender==='all'||t.coachGender===state.trainingGender)&&(!state.trainingCourts.length||state.trainingCourts.includes(t.courtId))&&(state.trainingFormat==='all'||t.format===state.trainingFormat));}
function trainingResults(){const list=filteredTrainings();return `<div class="results-head"><strong>На ближайшие даты</strong><span>${list.length} найдено</span></div>${list.length?list.map(trainingCard).join(''):'<div class="card empty"><strong>Тренировок по фильтрам нет</strong><div class="muted">Выберите другие корты или формат.</div></div>'}`;}
function trainingFilters(){const chosen=state.trainingCourts.length;return `<div class="search-panel training-filters"><label class="field">Вид спорта<select id="training-sport-filter"><option value="all">Теннис и падел</option><option value="tennis" ${state.trainingSport==='tennis'?'selected':''}>Теннис</option><option value="padel" ${state.trainingSport==='padel'?'selected':''}>Падел</option></select></label><div class="filter-row"><label class="field">Пол тренера<select id="training-gender-filter"><option value="all">Любой пол</option><option value="female" ${state.trainingGender==='female'?'selected':''}>Женщина</option><option value="male" ${state.trainingGender==='male'?'selected':''}>Мужчина</option></select></label><label class="field">Формат<select id="training-format-filter"><option value="all">Любой формат</option><option value="individual" ${state.trainingFormat==='individual'?'selected':''}>Индивидуальная</option><option value="split" ${state.trainingFormat==='split'?'selected':''}>Сплит</option><option value="group" ${state.trainingFormat==='group'?'selected':''}>Групповая</option></select></label></div><details class="court-multiselect"><summary>Корты · ${chosen?`выбрано ${chosen}`:'все'}</summary><div class="court-checks">${state.catalog.courts.map(c=>`<label><input type="checkbox" data-training-court="${esc(c.id)}" ${state.trainingCourts.includes(c.id)?'checked':''}><span><strong>${esc(c.name)}</strong><small>${c.sport==='padel'?'Падел':'Теннис'} · ${esc(c.address)}</small></span></label>`).join('')}</div></details></div>`;}
function training(){return `<div class="content subpage"><div class="page-heading"><div><h1 class="page-title">Тренировки</h1><p class="lead">Занятия, опубликованные тренерами.</p></div>${state.me?.role==='coach'?'<button class="add-game" data-page="create-training" aria-label="Создать тренировку">＋</button>':''}</div>${trainingFilters()}<div id="training-results">${trainingResults()}</div>${weatherCredit()}${state.me?.role==='coach'?'<button class="button" data-page="create-training">＋ Создать тренировку</button>':''}</div>`;}
function trainingDetail(t){const available=t.seats-t.members.length,own=t.coachId===state.me?.id;return `<div class="content subpage"><div class="detail-cover"><div><span class="eyebrow">${t.sport==='padel'?'ПАДЕЛ':'ТЕННИС'} · ${trainingFormat[t.format]||'Тренировка'}</span><h1>${esc(t.courtName)}</h1></div></div><div class="form-card"><button class="participant-row coach-link" data-user="${esc(t.coachId)}"><span class="avatar">${avatar({name:t.coachName,photoData:t.coachPhotoData,avatarId:t.coachAvatarId})}</span><span><strong>Тренер - ${esc(t.coachName)}</strong><small>Тренерский стаж: ${t.coachYears==null?'не указан':`${t.coachYears} лет`}</small></span><span class="participant-next">Профиль →</span></button></div><div class="detail-grid"><div class="stat"><small>Дата и время · МСК</small><strong>${day(t.startsAt)} · ${hour(t.startsAt)}</strong></div><div class="stat"><small>Стоимость</small><strong>${t.price} ₽ / чел.</strong></div><div class="stat"><small>Формат</small><strong>${trainingFormat[t.format]||'Тренировка'}</strong></div><div class="stat"><small>Длительность</small><strong>${t.duration} минут</strong></div><div class="stat"><small>Уровень</small><strong>${t.ntrpMin==null?'Без ограничений':`NTRP ${t.ntrpMin}–${t.ntrpMax}`}</strong></div><div class="stat"><small>Свободные места</small><strong>${available} из ${t.seats}</strong></div></div><div class="notice">📍 Краснодар, ${esc(t.courtAddress)}</div>${t.note?`<div class="form-card"><strong>О тренировке</strong><p class="muted">${esc(t.note)}</p></div>`:''}<div class="form-card"><h3>Записались · ${t.members.length}/${t.seats}</h3>${participantRows(t.members)}</div>${t.cancelled?'<p class="notice">Тренировка отменена тренером.</p>':own?'':t.joined?`<button class="button light" data-training-action="leave" data-training-id="${t.id}">Отменить запись</button>`:available?`<button class="button" data-training-action="join" data-training-id="${t.id}">Записаться</button>`:'<p class="notice">Свободных мест нет.</p>'}${listingControls('training',t)}</div>`;}
function listingControls(kind,item){const own=(kind==='game'?item.creatorId:item.coachId)===state.me?.id,id=item.id;return `<div class="owner-controls">${item.cancelled?'<p class="notice">Объявление отменено. Запись закрыта.</p>':''}<button class="button light" data-chat="${kind}:${id}">${own?'Сообщения по объявлению':'Написать автору'}</button>${own&&!item.cancelled&&Date.parse(item.startsAt)>Date.now()&&!(kind==='game'&&item.result)?`<button class="small-btn outline" data-edit="${kind}:${id}">✎ Редактировать</button>${state.confirmCancel===kind+':'+id?`<p class="notice">Отменить объявление? Записавшиеся увидят отметку об отмене.</p><button class="small-btn cancel-listing" data-confirm-cancel="${kind}:${id}">Да, отменить</button><button class="small-btn outline" data-dismiss-cancel>Оставить</button>`:`<button class="small-btn cancel-listing" data-cancel="${kind}:${id}">Отменить объявление</button>`}`:''}</div>`;}
function contactDetails(u){return `<div class="card contact-card"><strong>Контакты</strong><div class="contact-links">${u.phone?`<a href="tel:${esc(u.phone.replace(/[^+\d]/g,''))}">☎ ${esc(u.phone)}</a>`:''}${u.telegramContact?`<a href="https://t.me/${esc(u.telegramContact)}" target="_blank" rel="noopener noreferrer">Telegram · @${esc(u.telegramContact)}</a>`:''}${!u.phone&&!u.telegramContact?'<span class="muted">Контакты не указаны.</span>':''}</div></div>`;}
function publicProfile(u){return `<div class="content subpage"><h1 class="page-title">Профиль участника</h1><div class="profile-banner"><span class="avatar">${avatar(u)}</span><div><h2>${esc(u.name)}</h2><p>${u.role==='coach'?'Тренер':'Игрок'} · ${esc(u.city||'Краснодар')} · ${u.gender==='female'?'женщина':u.gender==='male'?'мужчина':'пол не указан'}</p></div></div><div class="card profile-info"><strong>О себе</strong><p class="muted">${esc(u.about||'Информация пока не добавлена.')}</p><div class="profile-facts">${u.role==='coach'?`<span>Игра: ${sportNames(u.coachSports)}</span>`:''}<span>Стаж игры: ${u.playingYears==null?'не указан':`${u.playingYears} лет`}</span>${u.role==='coach'?`<span>Тренерский стаж: ${u.coachYears==null?'не указан':`${u.coachYears} лет`}</span>`:`<span>NTRP: ${u.ntrpLevel==null?'не указан':Number(u.ntrpLevel).toFixed(1)}</span>`}</div></div>${contactDetails(u)}</div>`;}
function createTrainingPage(){const allowed=state.me?.coachSports?.length?state.me.coachSports:['tennis','padel'],first=allowed[0];return `<div class="content"><h1 class="page-title">Создать тренировку</h1><p class="lead">Опубликуйте формат, площадку, время и цену.</p><form id="training-form"><div class="form-card"><h3>Вид спорта и формат</h3><label class="field">Тренировка<select name="sport" required>${allowed.map(s=>`<option value="${s}">${s==='tennis'?'🎾 Теннис':'Падел'}</option>`).join('')}</select></label><label class="field">Тип тренировки<select name="format"><option value="individual">Индивидуальная · 1 человек</option><option value="split">Сплит · 2 человека</option><option value="group">Групповая · 3–6 человек</option></select></label><label class="field" id="group-seats" hidden>Количество игроков<select name="seats"><option value="3">3 человека</option><option value="4">4 человека</option><option value="5">5 человек</option><option value="6">6 человек</option></select></label><div class="row"><label class="field">NTRP от<select name="ntrpMin"><option value="">Без уровня</option>${Object.keys(levelDescriptions.tennis).map(v=>`<option value="${v}">${v}</option>`).join('')}</select></label><label class="field">NTRP до<select name="ntrpMax"><option value="">Без уровня</option>${Object.keys(levelDescriptions.tennis).map(v=>`<option value="${v}">${v}</option>`).join('')}</select></label></div><p class="hint">Оставьте оба поля пустыми, если уровень не важен.</p></div><div class="form-card"><h3>Где и когда</h3><label class="field">Корт<select name="courtId" required>${courtOptions(first)}</select></label><div class="row"><label class="field">Дата<input type="date" name="date" min="${tomorrow()}" value="${tomorrow()}" required></label><label class="field">Время<input type="time" name="time" value="18:00" required></label></div><div class="row"><label class="field">Длительность<select name="duration"><option value="60">60 мин</option><option value="90" selected>90 мин</option><option value="120">120 мин</option></select></label><label class="field">₽ с человека<input type="number" name="price" min="0" max="100000" step="1" required></label></div><label class="field">Описание<textarea name="note" maxlength="240" placeholder="Что будет на тренировке"></textarea></label></div><div class="notice">Публикация не бронирует корт и не принимает оплату. Согласуйте площадку отдельно.</div><button class="button" type="submit">Опубликовать тренировку</button></form></div>`;}
function profile(){const u=state.me,level=u.ntrpLevel;return `<div class="content subpage"><h1 class="page-title">Мой профиль</h1><div class="profile-banner"><span class="avatar">${avatar(u)}</span><div><h2>${esc(u.name)}</h2><p>${u.role==='coach'?'Тренер':'Игрок'} · ${esc(u.city||'Краснодар')} · ${u.gender==='female'?'женщина':u.gender==='male'?'мужчина':'пол не указан'}</p></div></div><button class="button light profile-edit" data-page="edit-profile">✎ Редактировать профиль</button>${u.role==='coach'?'<button class="button" data-page="create-training">＋ Создать тренировку</button>':`<div class="rating-box profile-level"><span>🎾 Уровень тенниса · NTRP</span><strong>${level==null?'Не указан':Number(level).toFixed(1)}</strong><p class="muted">${level==null?'Выберите свой уровень по описанию навыков.':esc(levelDescriptions.tennis[Number(level).toFixed(1)])}</p></div>`}<div class="card"><strong>О себе</strong><p class="muted">${esc(u.about||'Расскажите немного о себе в настройках профиля.')}</p><div class="muted">${u.role==='coach'?`Игра: ${sportNames(u.coachSports)} · `:''}Стаж игры: ${u.playingYears==null?'не указан':`${u.playingYears} лет`}${u.role==='coach'?` · Тренерский стаж: ${u.coachYears??'не указан'} лет`:''}</div></div>${contactDetails(u)}${u.role==='coach'?`<div class="section-head"><h2>Мои тренировки</h2></div>${state.trainings.filter(t=>t.coachId===u.id).map(trainingCard).join('')||'<div class="card empty"><strong>Пока нет тренировок</strong></div>'}`:`<p class="notice">Уровень NTRP вы указываете сами. Подтверждение счёта игры не меняет его автоматически.</p><div class="section-head"><h2>Мои тренировки</h2></div>${state.trainings.filter(t=>t.joined).map(trainingCard).join('')||'<div class="card empty">Нет записей на тренировки</div>'}<div class="section-head"><h2>Мои игры</h2></div>${state.games.filter(g=>g.joined).length?state.games.filter(g=>g.joined).map(gameCard).join(''):'<div class="card empty"><strong>Ещё нет игр</strong></div>'}`}</div>`;}

function sportNames(sports){return (sports?.length?sports:['tennis','padel']).map(s=>s==='tennis'?'теннис':'падел').join(' и ');}
function avatarGallery(){return `<div class="avatar-groups">${['Мужские','Женские'].map(group=>`<div><span class="avatar-group-title">${group}</span><div class="avatar-grid">${avatarChoices.filter(x=>x[2]===group).map(([id,label])=>`<button type="button" class="avatar-choice ${state.avatarId===id&&!state.profilePhotoData?'selected':''}" data-avatar="${id}" aria-pressed="${state.avatarId===id&&!state.profilePhotoData}">${tennisAvatar(id)}<span>${label}</span></button>`).join('')}</div></div>`).join('')}</div>`;}
function identityFields(u,registration=false){const isCoach=(registration?state.registrationRole:u.role)==='coach',level=u.ntrpLevel==null?'':Number(u.ntrpLevel).toFixed(1);return `<div class="form-card"><h3>Личные данные</h3><label class="field">Имя<input name="name" value="${esc(u.name||'')}" maxlength="60" required></label>${registration?`<div class="notice">Вы выбрали: ${state.registrationRole==='coach'?'тренер':'игрок'} <button type="button" class="text-btn" data-register-back>Изменить</button></div><input type="hidden" name="role" value="${state.registrationRole}">`:`<label class="field">Я<select name="role"><option value="player" ${u.role!=='coach'?'selected':''}>Игрок</option><option value="coach" ${u.role==='coach'?'selected':''}>Тренер</option></select></label>`}<div class="row"><label class="field">Пол<select name="gender" required><option value="">Выберите</option><option value="male" ${u.gender==='male'?'selected':''}>Мужчина</option><option value="female" ${u.gender==='female'?'selected':''}>Женщина</option></select></label><label class="field">Стаж игры, лет<input type="number" name="playingYears" min="0" max="80" step="1" value="${u.playingYears??''}" required></label></div><label class="field">Город<select name="city" required>${(state.config.cities||['Краснодар']).map(city=>`<option value="${esc(city)}" ${city===(u.city||'Краснодар')?'selected':''}>${esc(city)}</option>`).join('')}</select></label><div class="row"><label class="field">Телефон · по желанию<input type="tel" name="phone" inputmode="tel" maxlength="30" placeholder="+7 999 123-45-67" value="${esc(u.phone||'')}"></label><label class="field">Telegram · по желанию<input name="telegramContact" autocapitalize="none" maxlength="40" placeholder="@username" value="${esc(u.telegramContact?'@'+u.telegramContact:'')}"></label></div><p class="hint">Указанные контакты будут видны другим пользователям в вашем профиле.</p><label class="field">Информация о себе<textarea name="about" maxlength="500" placeholder="${isCoach?'Расскажите о вашем тренерском опыте':'Как часто играете, что ищете в приложении'}">${esc(u.about||'')}</textarea></label></div><div class="form-card" id="profile-ntrp-card" ${isCoach?'hidden':''}><h3>Уровень тенниса · NTRP</h3><label class="field">Ваш уровень<select name="ntrpLevel" ${isCoach?'':'required'}><option value="">Выберите уровень</option>${Object.keys(levelDescriptions.tennis).map(v=>`<option value="${v}" ${level===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="level-explainer" id="profile-level-description">${level?esc(levelDescriptions.tennis[level]):'Выберите уровень, чтобы прочитать описание навыков.'}</div><details class="level-guide"><summary>Описание всех уровней NTRP</summary><div>${levelGuide('tennis')}</div></details></div><div class="form-card" id="coach-sports-card" ${isCoach?'':'hidden'}><h3>Игра</h3><p class="hint">Какие тренировки вы проводите?</p><div class="seg coach-sports"><label><input type="checkbox" name="coachSports" value="tennis" ${(u.coachSports||['tennis','padel']).includes('tennis')?'checked':''}> 🎾 Теннис</label><label><input type="checkbox" name="coachSports" value="padel" ${(u.coachSports||['tennis','padel']).includes('padel')?'checked':''}> ${padelIcon()} Падел</label></div></div><div class="form-card"><h3>Фото или теннисная аватарка</h3><div class="profile-photo"><span class="avatar" id="photo-preview">${avatar({name:u.name,photoData:state.profilePhotoData,avatarId:state.avatarId})}</span><div><strong>Как вас увидят другие</strong><p class="hint">Загрузите фото или выберите один из шести образов.</p></div></div><label class="field">Своя фотография<input type="file" id="profile-photo-input" accept="image/*"></label><button type="button" class="text-btn" data-remove-photo>Убрать фото</button>${avatarGallery()}</div>${!registration?`<div class="form-card" id="coach-years-card" ${u.role==='coach'?'':'hidden'}><h3>Для тренера</h3><label class="field">Тренерский стаж, лет<input type="number" name="coachYears" min="0" max="80" step="1" value="${u.coachYears??''}" ${u.role==='coach'?'required':''}></label></div>`:''}`;}
function profileEditor(){return `<div class="content"><h1 class="page-title">Редактировать профиль</h1><form id="profile-form">${identityFields(state.me)}<button class="button" type="submit">Сохранить профиль</button></form></div>`;}
function registration(){if(state.registrationStep===1)return `<div class="content onboarding"><div class="step-count">Регистрация · шаг 1 из ${state.registrationRole==='coach'?3:2}</div><h1 class="page-title">Добро пожаловать в Tennis GO</h1><p class="lead">Выберите, как будете пользоваться приложением.</p><div class="role-grid"><button data-role="player" class="role-card"><span>🎾</span><strong>Я игрок</strong><small>Ищу игру, партнёра или тренировку</small></button><button data-role="coach" class="role-card"><span>◷</span><strong>Я тренер</strong><small>Провожу тренировки и играю</small></button></div></div>`;if(state.registrationStep===3)return `<div class="content onboarding"><div class="step-count">Регистрация · шаг 3 из 3</div><h1 class="page-title">Тренерский опыт</h1><p class="lead">Укажите, сколько лет вы проводите тренировки.</p><form id="coach-registration-form"><div class="form-card"><label class="field">Тренерский стаж, лет<input type="number" name="coachYears" min="0" max="80" step="1" value="${state.registrationDraft?.coachYears??''}" required></label></div><button class="button" type="submit">Завершить регистрацию</button></form></div>`;return `<div class="content onboarding"><div class="step-count">Регистрация · шаг 2 из ${state.registrationRole==='coach'?3:2}</div><h1 class="page-title">Расскажите о себе</h1><p class="lead">Эти данные помогут другим игрокам познакомиться с вами.</p><form id="registration-form">${identityFields(state.registrationDraft||state.me,true)}<button class="button" type="submit">${state.registrationRole==='coach'?'Далее →':'Завершить регистрацию'}</button></form></div>`;}
function identityPayload(form){return {name:String(form.get('name')||'').trim(),role:form.get('role'),gender:form.get('gender'),playingYears:Number(form.get('playingYears')),ntrpLevel:form.get('role')==='coach'?null:form.get('ntrpLevel')?Number(form.get('ntrpLevel')):null,about:form.get('about'),city:form.get('city'),phone:String(form.get('phone')||'').trim(),telegramContact:String(form.get('telegramContact')||'').trim().replace(/^@/,''),coachSports:form.get('role')==='coach'?form.getAll('coachSports'):[],coachYears:form.get('role')==='coach'?(form.has('coachYears')?Number(form.get('coachYears')):state.me?.coachYears??null):null,photoData:state.profilePhotoData,avatarId:state.avatarId};}
async function saveIdentity(payload){if(payload.role==='coach'&&!payload.coachSports.length)throw Error('Выберите теннис, падел или оба вида спорта');const data=await api('/profile','POST',payload);state.me=data.user;if(state.form==='edit-profile')state.history.pop();state.form='';await refresh();if(state.pendingGame){try{state.detail=(await api(`/games/${state.pendingGame}`)).game;}catch{toast('Игра по ссылке не найдена');}state.pendingGame=null;}render();toast('Профиль сохранён');}
async function imageData(file){
 if(!file.type.startsWith('image/'))throw Error('Выберите файл изображения');
 if(file.size>10_000_000)throw Error('Фото должно быть меньше 10 МБ');
 const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Не удалось прочитать фото'));reader.readAsDataURL(file);});
 let img;try{img=await new Promise((resolve,reject)=>{const picture=new Image();picture.onload=()=>resolve(picture);picture.onerror=()=>reject(Error('Фото не распознано'));picture.src=source;});}
 catch{try{img=await createImageBitmap(file);}catch{throw Error('Не удалось открыть фото. Попробуйте JPG или PNG вместо HEIC.');}}
 const canvas=document.createElement('canvas');canvas.width=canvas.height=400;
 const ctx=canvas.getContext('2d');if(!ctx)throw Error('Не удалось обработать фото');
 const width=img.naturalWidth||img.width,height=img.naturalHeight||img.height,side=Math.min(width,height);if(!side)throw Error('Фото повреждено');
 ctx.drawImage(img,(width-side)/2,(height-side)/2,side,side,0,0,400,400);
 img.close?.();
 let data=canvas.toDataURL('image/jpeg',.8);if(data.length>340000)data=canvas.toDataURL('image/jpeg',.6);
 if(!data.startsWith('data:image/jpeg;base64,')||data.length>340000)throw Error('Не удалось уменьшить фото, выберите JPG или PNG');
 return data;
}
function selectedOption(value,selected,label){return `<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`;}
function editGamePage(){const g=state.games.find(x=>x.id===state.editTarget?.id);if(!g)return '<div class="content">Игра не найдена</div>';return `<div class="content"><h1 class="page-title">Редактировать игру</h1><form id="edit-game-form" class="edit-listing"><div class="form-card"><label class="field">Вид спорта<select name="sport">${selectedOption('tennis',g.sport,'Теннис')}${selectedOption('padel',g.sport,'Падел')}</select></label><label class="field">Корт<select name="courtId" required>${courtOptions(g.sport,g.courtId)}</select></label><div class="row"><label class="field">Дата<input type="date" name="date" value="${dayKey(g.startsAt)}" required></label><label class="field">Время<input type="time" name="time" value="${hour(g.startsAt)}" required></label></div><div class="row"><label class="field">Игроков<select name="seats">${selectedOption(2,g.seats,'2 игрока')}${selectedOption(4,g.seats,'4 игрока · парная')}</select></label><label class="field">Тип<select name="kind">${selectedOption('friendly',g.kind,'Обычная')}${selectedOption('rating',g.kind,'С результатом')}</select></label></div><div class="row"><label class="field">Мин. уровень<select name="levelMin">${levelOptions(g.levelMin,g.sport)}</select></label><label class="field">Макс. уровень<select name="levelMax">${levelOptions(g.levelMax,g.sport)}</select></label></div><div class="row"><label class="field">Длительность<select name="duration">${[60,90,120].map(v=>selectedOption(v,g.duration,v+' мин')).join('')}</select></label><label class="field">₽ / чел.<input type="number" name="price" min="0" max="100000" value="${g.price}" required></label></div><label class="field">Кто может присоединиться<select name="opponentGender">${selectedOption('any',g.opponentGender,'Любой пол')}${selectedOption('female',g.opponentGender,'Женщины')}${selectedOption('male',g.opponentGender,'Мужчины')}</select></label><label class="field">Комментарий<textarea name="note" maxlength="240">${esc(g.note||'')}</textarea></label></div><button class="button" type="submit">Сохранить изменения</button></form></div>`;}
function editTrainingPage(){const t=state.trainings.find(x=>x.id===state.editTarget?.id);if(!t)return '<div class="content">Тренировка не найдена</div>';const allowed=state.me?.coachSports?.length?state.me.coachSports:['tennis','padel'];return `<div class="content"><h1 class="page-title">Редактировать тренировку</h1><form id="edit-training-form" class="edit-listing"><div class="form-card"><label class="field">Вид спорта<select name="sport">${allowed.map(v=>selectedOption(v,t.sport,v==='tennis'?'Теннис':'Падел')).join('')}</select></label><label class="field">Корт<select name="courtId" required>${courtOptions(t.sport,t.courtId)}</select></label><label class="field">Формат<select name="format">${selectedOption('individual',t.format,'Индивидуальная')}${selectedOption('split',t.format,'Сплит')}${selectedOption('group',t.format,'Группа')}</select></label><label class="field" id="edit-group-seats" ${t.format==='group'?'':'hidden'}>Игроков в группе<select name="seats">${[3,4,5,6].map(v=>selectedOption(v,t.seats,v+' человека')).join('')}</select></label><div class="row"><label class="field">NTRP от<select name="ntrpMin">${selectedOption('',t.ntrpMin??'','Без уровня')}${levelOptions(t.ntrpMin,'tennis')}</select></label><label class="field">NTRP до<select name="ntrpMax">${selectedOption('',t.ntrpMax??'','Без уровня')}${levelOptions(t.ntrpMax,'tennis')}</select></label></div><div class="row"><label class="field">Дата<input type="date" name="date" value="${dayKey(t.startsAt)}" required></label><label class="field">Время<input type="time" name="time" value="${hour(t.startsAt)}" required></label></div><div class="row"><label class="field">Длительность<select name="duration">${[60,90,120].map(v=>selectedOption(v,t.duration,v+' мин')).join('')}</select></label><label class="field">₽ / чел.<input type="number" name="price" min="0" max="100000" value="${t.price}" required></label></div><label class="field">Описание<textarea name="note" maxlength="240">${esc(t.note||'')}</textarea></label></div><button class="button" type="submit">Сохранить изменения</button></form></div>`;}
function peoplePage(){return `<div class="content subpage"><h1 class="page-title">Игроки и тренеры</h1><p class="lead">Зарегистрированные пользователи Tennis GO.</p><form id="people-search-form" class="search-panel"><label class="field">Поиск по имени<input name="q" value="${esc(state.peopleQuery)}" placeholder="Имя игрока или тренера"></label><button class="button light" type="submit">Найти</button></form><div class="results-head"><strong>Пользователи</strong><span>${state.people.length} показано</span></div>${state.people.length?state.people.map(u=>`<article class="card person-card"><span class="avatar">${avatar(u)}</span><span class="person-info"><strong>${esc(u.name)}</strong><small>${u.role==='coach'?'Тренер':'Игрок'} · ${esc(u.city||'Краснодар')}</small></span><span class="person-actions"><button class="small-btn outline" data-user="${esc(u.id)}">Профиль</button><button class="small-btn" data-direct="${esc(u.id)}" data-name="${esc(u.name)}">Написать</button></span></article>`).join(''):'<div class="card empty">Пользователей по запросу пока нет.</div>'}${state.peopleMore?'<button class="button light" data-more-people>Показать ещё</button>':''}</div>`;}
function inboxPage(){return `<div class="content subpage"><h1 class="page-title">Чаты ${state.unread?`<span class="inbox-counter">${state.unread}</span>`:''}</h1><p class="lead">Ваши диалоги с игроками и тренерами.</p>${state.inbox.length?state.inbox.map(t=>`<button class="card inbox-thread ${t.unread?'has-unread':''}" data-inbox-thread="${esc(t.key)}"><span class="avatar">${avatar({name:t.peerName,avatarId:t.peerAvatarId,photoData:t.peerPhotoData})}</span><span class="inbox-thread-body"><strong>${esc(t.peerName)}</strong><small>${esc(t.title)}</small><span>${esc(t.lastMessage)}</span></span>${t.unread?`<b class="unread-pill">${t.unread}</b>`:''}</button>`).join(''):'<div class="card empty"><strong>Диалогов пока нет</strong><p>Откройте раздел «Люди» или объявление и нажмите «Написать».</p></div>'}</div>`;}
function chatMessages(c){return c.messages.length?c.messages.map(m=>`<div class="chat-bubble ${m.senderId===state.me.id?'mine':''}">${esc(m.body)}<small>${day(m.createdAt)} · ${hour(m.createdAt)}</small></div>`).join(''):'<p class="muted">Сообщений пока нет. Напишите первым.</p>';}
function chatPage(){const c=state.chat;if(!c)return '';const title=c.kind==='direct'?'Личный чат':c.kind==='game'?'Игра':'Тренировка';return `<div class="content subpage"><h1 class="page-title">Сообщения · ${title}</h1>${c.peerId?`<p class="lead">${esc(c.peerName||'Автор объявления')}</p><div class="chat-messages">${chatMessages(c)}</div><button class="text-btn" data-chat-refresh>↻ Обновить сообщения</button><form id="chat-form" class="chat-form"><label class="field">Сообщение<textarea name="message" maxlength="500" required placeholder="Напишите сообщение"></textarea></label><button class="button" type="submit">Отправить</button></form>`:`<p class="lead">Выберите диалог по этому объявлению.</p>${c.threads?.length?c.threads.map(p=>`<button class="participant-row" data-chat-peer="${esc(p.id)}"><span class="avatar">${avatar(p)}</span><strong>${esc(p.name)}</strong><span class="participant-next">Открыть →</span></button>`).join(''):'<div class="card empty">Пока никто не написал.</div>'}<button class="text-btn" data-chat-refresh>↻ Обновить диалоги</button>`}</div>`;}

function render(){if(state.loading){app.innerHTML='<div class="splash">🎾 Tennis GO</div>';return;}const registering=!state.me?.registered,page=registering?registration():state.chat?chatPage():state.form==='edit-game'?editGamePage():state.form==='edit-training'?editTrainingPage():state.userProfile?publicProfile(state.userProfile):state.trainingDetail?trainingDetail(state.trainingDetail):state.detail?gameDetail(state.detail):state.form==='create'?createPage():state.form==='create-training'?createTrainingPage():state.form==='edit-profile'?profileEditor():({home,games:gamesPage,training,people:peoplePage,chats:inboxPage,profile})[state.tab]?.()||home();const showBack=registering||!!state.chat||!!state.userProfile||!!state.trainingDetail||!!state.detail||!!state.form||state.tab!=='home';app.innerHTML=`<main class="app">${logo()}${showBack?'<div class="global-back"><button data-back aria-label="Вернуться на предыдущий экран">← Назад</button></div>':''}${page}${registering?'':nav()}</main>`;tg?.BackButton?.[showBack?'show':'hide']?.();}
function snapshot(){return {tab:state.tab,form:state.form,detailId:state.detail?.id||null,trainingId:state.trainingDetail?.id||null,userProfile:state.userProfile,chat:state.chat};}
function pushView(){state.history.push(snapshot());}
function back(){if(!state.me?.registered){if(state.registrationStep>1){state.registrationStep--;render();}else if(tg?.close)tg.close();else toast('Это первый экран');return;}const previous=state.history.pop();if(previous){state.tab=previous.tab;state.form=previous.form;state.detail=previous.detailId?state.games.find(g=>g.id===previous.detailId)||null:null;state.trainingDetail=previous.trainingId?state.trainings.find(t=>t.id===previous.trainingId)||null:null;state.userProfile=previous.userProfile;state.chat=previous.chat||null;state.confirmCancel=null;render();return;}if(state.form||state.detail||state.trainingDetail||state.userProfile||state.chat||state.tab!=='home'){state.form='';state.detail=null;state.trainingDetail=null;state.userProfile=null;state.chat=null;state.tab='home';render();return;}if(tg?.close)tg.close();else toast('Это главный экран');}
function openGame(id){pushView();state.detail=state.games.find(g=>g.id===id)||null;state.trainingDetail=null;state.userProfile=null;state.chat=null;state.form='';render();}
function openTraining(id){const found=state.trainings.find(t=>t.id===id);if(!found)return toast('Тренировка не найдена');pushView();state.trainingDetail=found;state.detail=null;state.userProfile=null;state.chat=null;state.form='';render();}
async function openChat(kind,id,peerId=null){const listing=kind==='game'?state.games.find(x=>x.id===id):state.trainings.find(x=>x.id===id);if(!listing)throw Error('Объявление не найдено');const authorId=kind==='game'?listing.creatorId:listing.coachId,own=authorId===state.me.id;const peer=own?peerId:authorId;let data=own&&!peer?await api(`/chats/${kind}/${id}`):await api(`/chats/${kind}/${id}/${peer}`);pushView();state.chat={kind,id,authorId,peerId:peer||null,peerName:own?state.chat?.threads?.find(x=>x.id===peer)?.name||'Участник':kind==='training'?listing.coachName:'Автор игры',messages:data.messages||[],threads:data.threads||[]};state.form='';render();}
async function refreshChat(silent=false){const c=state.chat;if(!c)return;const data=await api(c.kind==='direct'?`/direct/${c.peerId}`:`/chats/${c.kind}/${c.id}${c.peerId?'/'+c.peerId:''}`);if(state.chat!==c)return;const before=JSON.stringify(c.messages);c.messages=data.messages||[];c.threads=data.threads||[];if(silent&&c.peerId){if(before!==JSON.stringify(c.messages)){const box=document.querySelector('.chat-messages');if(box){box.innerHTML=chatMessages(c);box.scrollTop=box.scrollHeight;}}}else render();}
async function openDirect(id,name){const data=await api('/direct/'+encodeURIComponent(id));pushView();state.chat={kind:'direct',id,peerId:id,peerName:name||data.peer?.name||'Пользователь',messages:data.messages||[],threads:[]};state.form='';render();loadInbox(false).catch(()=>{});}
async function openUser(id){const data=await api('/users/'+encodeURIComponent(id));pushView();state.userProfile=data.user;state.form='';render();}
function startAt(form){const d=form.get('date'),t=form.get('time');return new Date(`${d}T${t}:00+03:00`).toISOString();}
async function doAction(action){const g=state.detail;if(!g)return;if(action==='share'){const link=state.config.botUsername?`https://t.me/${state.config.botUsername}?startapp=game_${g.id}`:`${location.origin}/?game=${g.id}`;const msg=`🎾 ${g.sport==='tennis'?'Теннис':'Падел'} · ${day(g.startsAt)} ${hour(g.startsAt)} · ${g.venue}. Присоединяйся: ${link}`;if(tg?.initData&&state.config.botUsername){tg.openTelegramLink(`https://t.me/share/url?url=${encodeURIComponent(link)}&text=${encodeURIComponent(msg)}`);}else{await navigator.clipboard.writeText(msg);toast('Приглашение скопировано');}return;}
  const data=await api(`/games/${g.id}/${action}`,'POST');state.detail=data.game;await refresh();state.detail=state.games.find(x=>x.id===g.id)||data.game;render();toast(({join:'Вы в игре!',leave:'Вы вышли из игры',confirm:'Результат подтверждён'})[action]);}
app.addEventListener('click',async e=>{const el=e.target.closest('[data-direct],[data-inbox-thread],[data-more-people],[data-chat],[data-chat-peer],[data-chat-refresh],[data-edit],[data-cancel],[data-confirm-cancel],[data-dismiss-cancel],[data-role],[data-avatar],[data-register-back],[data-my-level],[data-training-action],[data-training],[data-user],[data-tab],[data-page],[data-filter],[data-when],[data-available],[data-reset-filters],[data-game],[data-action],[data-back],[data-remove-photo]');if(!el)return;try{
 if(el.dataset.direct){await openDirect(el.dataset.direct,el.dataset.name);}
 else if(el.dataset.inboxThread){const t=state.inbox.find(x=>x.key===el.dataset.inboxThread);if(!t)return;if(t.kind==='direct')await openDirect(t.peerId,t.peerName);else await openChat(t.kind,t.listingId,t.peerId);}
 else if(el.hasAttribute('data-more-people')){await loadPeople();}
 else if(el.dataset.chat){const [kind,id]=el.dataset.chat.split(':');await openChat(kind,id);}
 else if(el.dataset.chatPeer){await openChat(state.chat.kind,state.chat.id,el.dataset.chatPeer);}
 else if(el.hasAttribute('data-chat-refresh')){await refreshChat();}
 else if(el.dataset.edit){const [kind,id]=el.dataset.edit.split(':');pushView();state.editTarget={kind,id};state.form=kind==='game'?'edit-game':'edit-training';state.detail=null;state.trainingDetail=null;state.chat=null;render();}
 else if(el.dataset.cancel){state.confirmCancel=el.dataset.cancel;render();}
 else if(el.hasAttribute('data-dismiss-cancel')){state.confirmCancel=null;render();}
 else if(el.dataset.confirmCancel){const [kind,id]=el.dataset.confirmCancel.split(':');await api(`/${kind==='game'?'games':'trainings'}/${id}`,'DELETE');await refresh();state.confirmCancel=null;state.detail=kind==='game'?state.games.find(x=>x.id===id):null;state.trainingDetail=kind==='training'?state.trainings.find(x=>x.id===id):null;render();toast('Объявление отменено');}
 else if(el.dataset.role){state.registrationRole=el.dataset.role;state.registrationStep=2;state.registrationDraft=null;state.profilePhotoData=state.me?.photoData||null;state.avatarId=state.me?.avatarId||null;render();}
 else if(el.hasAttribute('data-register-back'))back();
 else if(el.dataset.avatar){state.avatarId=el.dataset.avatar;state.profilePhotoData=null;document.querySelector('#photo-preview').innerHTML=tennisAvatar(state.avatarId);document.querySelector('#profile-photo-input').value='';document.querySelectorAll('[data-avatar]').forEach(button=>{button.classList.toggle('selected',button.dataset.avatar===state.avatarId);button.setAttribute('aria-pressed',button.dataset.avatar===state.avatarId);});}
 else if(el.dataset.trainingAction){await api(`/trainings/${el.dataset.trainingId}/${el.dataset.trainingAction}`,'POST');await refresh();if(state.trainingDetail)state.trainingDetail=state.trainings.find(t=>t.id===el.dataset.trainingId)||null;render();toast(el.dataset.trainingAction==='join'?'Вы записаны на тренировку':'Запись отменена');}
 else if(el.dataset.user)await openUser(el.dataset.user);
 else if(el.dataset.training)openTraining(el.dataset.training);
 else if(el.dataset.tab){if(el.dataset.tab==='people'&&!state.people.length)await loadPeople(true);if(el.dataset.tab==='chats')await loadInbox(false);if(state.tab!==el.dataset.tab||state.detail||state.trainingDetail||state.userProfile||state.form)pushView();state.tab=el.dataset.tab;state.detail=null;state.trainingDetail=null;state.userProfile=null;state.chat=null;state.form='';render();}
 else if(el.dataset.page){pushView();state.form=el.dataset.page;state.detail=null;state.trainingDetail=null;state.userProfile=null;if(state.form==='edit-profile'){state.profilePhotoData=state.me.photoData||null;state.avatarId=state.me.avatarId||null;}render();}
 else if(el.hasAttribute('data-remove-photo')){state.profilePhotoData=null;document.querySelector('#photo-preview').innerHTML=avatar({name:state.me.name,avatarId:state.avatarId});document.querySelector('#profile-photo-input').value='';document.querySelectorAll('[data-avatar]').forEach(button=>button.classList.toggle('selected',button.dataset.avatar===state.avatarId));}
 else if(el.dataset.filter){state.filter=el.dataset.filter;if(state.court!=='all'&&!state.catalog.courts.some(c=>c.id===state.court&&(state.filter==='all'||c.sport===state.filter)))state.court='all';render();}
 else if(el.dataset.when){state.when=el.dataset.when;render();}
 else if(el.hasAttribute('data-my-level')){if(state.me?.ntrpLevel==null){toast('Укажите свой NTRP в профиле');return;}state.myLevelOnly=!state.myLevelOnly;render();}
 else if(el.hasAttribute('data-available')){state.availableOnly=!state.availableOnly;render();}
 else if(el.hasAttribute('data-reset-filters')){state.filter='all';state.when='all';state.court='all';state.genderFilter='all';state.myLevelOnly=false;state.availableOnly=false;render();}
 else if(el.dataset.game)openGame(el.dataset.game);
 else if(el.hasAttribute('data-back'))back();
 else if(el.dataset.action)await doAction(el.dataset.action);
 }catch(err){toast(err.message);}});
app.addEventListener('change',async e=>{if(e.target.id==='profile-photo-input'){if(!e.target.files?.[0])return;try{state.profilePhotoData=await imageData(e.target.files[0]);document.querySelector('#photo-preview').innerHTML=`<img src="${esc(state.profilePhotoData)}" alt="Фото профиля">`;document.querySelectorAll('[data-avatar]').forEach(button=>{button.classList.remove('selected');button.setAttribute('aria-pressed','false');});}catch(err){toast(err.message);}return;}if(e.target.name==='ntrpLevel'&&e.target.closest('#profile-form,#registration-form')){document.querySelector('#profile-level-description').textContent=levelDescriptions.tennis[e.target.value]||'Выберите уровень, чтобы прочитать описание навыков.';return;}if(e.target.name==='role'&&e.target.closest('#profile-form')){const coach=e.target.value==='coach',card=document.querySelector('#coach-years-card'),input=card.querySelector('input'),ntrp=document.querySelector('#profile-ntrp-card'),level=ntrp.querySelector('select[name=ntrpLevel]');card.hidden=!coach;input.required=coach;ntrp.hidden=coach;level.required=!coach;document.querySelector('#coach-sports-card').hidden=!coach;document.querySelector('textarea[name=about]').placeholder=coach?'Расскажите о вашем тренерском опыте':'Как часто играете, что ищете в приложении';return;}if(e.target.name==='sport'&&e.target.closest('#edit-training-form,#edit-game-form')){e.target.form.elements.courtId.innerHTML=courtOptions(e.target.value);return;}if(e.target.name==='format'&&e.target.closest('#edit-training-form')){document.querySelector('#edit-group-seats').hidden=e.target.value!=='group';return;}if(e.target.name==='sport'&&e.target.closest('#training-form')){e.target.form.elements.courtId.innerHTML=courtOptions(e.target.value);return;}if(e.target.name==='format'&&e.target.closest('#training-form')){document.querySelector('#group-seats').hidden=e.target.value!=='group';return;}if(e.target.id==='gender-filter'){state.genderFilter=e.target.value;render();return;}if(e.target.id==='court-filter'){state.court=e.target.value;render();return;}const form=e.target.closest('#create-form');if(!form)return;if(e.target.name==='sport')updateCreateChoices(form);else if(['kind','seats'].includes(e.target.name))syncGameFormat(form);else if(['courtId','levelMin','levelMax'].includes(e.target.name))updateCreateHints(form);});
app.addEventListener('change',e=>{if(e.target.id==='training-sport-filter')state.trainingSport=e.target.value;else if(e.target.id==='training-gender-filter')state.trainingGender=e.target.value;else if(e.target.id==='training-format-filter')state.trainingFormat=e.target.value;else if(e.target.dataset?.trainingCourt){const id=e.target.dataset.trainingCourt;state.trainingCourts=e.target.checked?[...state.trainingCourts,id]:state.trainingCourts.filter(x=>x!==id);e.target.closest('.court-multiselect').querySelector('summary').textContent='Корты · '+(state.trainingCourts.length?'выбрано '+state.trainingCourts.length:'все');}else return;const results=document.querySelector('#training-results');if(results)results.innerHTML=trainingResults();});
app.addEventListener('submit',async e=>{if(!['create-form','training-form','result-form','profile-form','registration-form','coach-registration-form','edit-game-form','edit-training-form','chat-form','people-search-form'].includes(e.target.id))return;e.preventDefault();const form=new FormData(e.target),button=e.target.querySelector('button[type=submit]');button.disabled=true;try{
 if(e.target.id==='people-search-form'){state.peopleQuery=String(form.get('q')||'').trim();await loadPeople(true);}
 else if(e.target.id==='chat-form'){const c=state.chat,data=await api(c.kind==='direct'?`/direct/${c.peerId}`:`/chats/${c.kind}/${c.id}/${c.peerId}`,'POST',{message:form.get('message')});c.messages=data.messages;render();loadInbox(false).catch(()=>{});}
 else if(e.target.id==='edit-game-form'){const id=state.editTarget.id,payload={sport:form.get('sport'),seats:Number(form.get('seats')),kind:form.get('kind'),courtId:form.get('courtId'),startsAt:startAt(form),duration:Number(form.get('duration')),price:Number(form.get('price')),levelMin:Number(form.get('levelMin')),levelMax:Number(form.get('levelMax')),opponentGender:form.get('opponentGender'),note:form.get('note')};const data=await api(`/games/${id}`,'PATCH',payload);await refresh();state.history.pop();state.form='';state.detail=state.games.find(g=>g.id===id)||data.game;render();toast('Игра обновлена');}
 else if(e.target.id==='edit-training-form'){const id=state.editTarget.id,format=form.get('format'),payload={sport:form.get('sport'),format,seats:format==='individual'?1:format==='split'?2:Number(form.get('seats')),courtId:form.get('courtId'),startsAt:startAt(form),duration:Number(form.get('duration')),ntrpMin:form.get('ntrpMin')?Number(form.get('ntrpMin')):null,ntrpMax:form.get('ntrpMax')?Number(form.get('ntrpMax')):null,price:Number(form.get('price')),note:form.get('note')};const data=await api(`/trainings/${id}`,'PATCH',payload);await refresh();state.history.pop();state.form='';state.trainingDetail=state.trainings.find(t=>t.id===id)||data.training;render();toast('Тренировка обновлена');}
 else if(e.target.id==='registration-form'){const payload=identityPayload(form);if(!payload.photoData&&!payload.avatarId)throw Error('Загрузите фото или выберите аватарку');if(payload.role==='coach'){if(!payload.coachSports.length)throw Error('Выберите теннис, падел или оба вида спорта');state.registrationDraft=payload;state.registrationStep=3;render();}else await saveIdentity(payload);}
 else if(e.target.id==='coach-registration-form'){await saveIdentity({...state.registrationDraft,coachYears:Number(form.get('coachYears'))});}
 else if(e.target.id==='profile-form'){await saveIdentity(identityPayload(form));}
 else if(e.target.id==='training-form'){const format=form.get('format'),payload={sport:form.get('sport'),format,seats:format==='individual'?1:format==='split'?2:Number(form.get('seats')),courtId:form.get('courtId'),startsAt:startAt(form),duration:Number(form.get('duration')),ntrpMin:form.get('ntrpMin')?Number(form.get('ntrpMin')):null,ntrpMax:form.get('ntrpMax')?Number(form.get('ntrpMax')):null,price:Number(form.get('price')),note:form.get('note')};if((payload.ntrpMin===null)!==(payload.ntrpMax===null)||payload.ntrpMin!==null&&payload.ntrpMin>payload.ntrpMax)throw Error('Укажите оба значения NTRP: «от» не выше «до»');await api('/trainings','POST',payload);await refresh();state.history.pop();state.form='';state.tab='training';render();toast('Тренировка опубликована');}
 else if(e.target.id==='create-form'){const payload={sport:form.get('sport'),seats:Number(form.get('seats')),kind:form.get('kind'),courtId:form.get('courtId'),city:'Краснодар',startsAt:startAt(form),duration:Number(form.get('duration')),price:Number(form.get('price')),levelMin:Number(form.get('levelMin')),levelMax:Number(form.get('levelMax')),opponentGender:form.get('opponentGender'),note:form.get('note')};if(payload.levelMin>payload.levelMax)throw Error('Уровень «От» не может быть выше «До»');const data=await api('/games','POST',payload);await refresh();state.form='';state.tab='games';openGame(data.game.id);toast('Игра создана · пригласите игроков');}
 else{const id=state.detail.id;const data=await api(`/games/${id}/result`,'POST',{score:form.get('score')});await refresh();state.detail=state.games.find(g=>g.id===id)||data.game;render();toast('Результат отправлен второму игроку');}
 }catch(err){button.disabled=false;toast(err.message);}});
tg?.BackButton?.onClick(back);
(async()=>{try{state.config=await api('/config');state.me=(await api('/me')).user;const param=tg?.initDataUnsafe?.start_param||new URLSearchParams(location.search).get('game');state.pendingGame=param?.startsWith('game_')?param.slice(5):param;if(state.me.registered){await refresh();if(state.pendingGame){try{state.detail=(await api(`/games/${state.pendingGame}`)).game;}catch{toast('Игра по ссылке не найдена');}state.pendingGame=null;}}state.loading=false;render();}catch(err){app.innerHTML=`<div class="splash" style="padding:25px;text-align:center">${esc(err.message)}<br><small>Откройте Mini App через Telegram или обновите страницу</small></div>`;}})();

window.setInterval?.(()=>{if(state.chat)refreshChat(true).catch(()=>{});if(state.me?.registered)loadInbox(false).catch(()=>{});},10000);
